#!/usr/bin/env bash
set -Eeuo pipefail

say(){ printf '\n\033[1;36m%s\033[0m\n' "$*"; }
fail(){ printf '\n\033[1;31mERROR: %s\033[0m\n' "$*" >&2; exit 1; }

[[ -f package.json ]] || fail "เปิด Terminal ที่ระดับเดียวกับ package.json ก่อน"
[[ -d .git ]] || fail "โฟลเดอร์นี้ไม่ใช่ Git repository"

CURRENT_VERSION=$(node -p "require('./package.json').version" 2>/dev/null || true)
[[ "$CURRENT_VERSION" == "9.6.0" || "$CURRENT_VERSION" == "9.7.0" ]] || fail "ต้องอัปเดตจาก v9.6.0 (พบ $CURRENT_VERSION)"

# อนุญาตให้มีเฉพาะไฟล์ติดตั้งนี้ที่ยังไม่ Commit
DIRTY=$(git status --porcelain | grep -vE '^\?\? v97\.sh$|^ M v97\.sh$|^A  v97\.sh$|^ D v97\.sh$' || true)
[[ -z "$DIRTY" ]] || fail "มีไฟล์อื่นยังไม่ Commit กรุณา Commit หรือยกเลิกก่อน:\n$DIRTY"

STAMP=$(date +%Y%m%d-%H%M%S)
BACKUP=".git/GOLD-PULSE-v9.6-backup-$STAMP.tar.gz"
PATCH_FILE=$(mktemp)
TEST_FILE=$(mktemp --suffix=.mjs)
cleanup(){ rm -f "$PATCH_FILE" "$TEST_FILE"; }
trap cleanup EXIT

say "1/6 สำรองไฟล์ v9.6 ไว้ที่ $BACKUP"
tar -czf "$BACKUP" \
  .env.example .gitignore CHANGELOG.md FILELIST.txt README.md \
  app/api/gold/route.js app/api/health/route.js app/api/scan/route.js \
  app/layout.js app/page.js lib/alerts.ts lib/config.ts package.json \
  public/manifest.webmanifest public/sw.js 2>/dev/null || true

say "2/6 ติดตั้ง GOLD PULSE X v9.7 OPPORTUNITY SIGNAL"
base64 -d > "$PATCH_FILE" <<'PATCH_BASE64'

PATCH_BASE64
tar -xzf "$PATCH_FILE" -C .
rm -f tsconfig.tsbuildinfo

say "3/6 ตรวจ Syntax และโครงสร้าง"
find app lib scripts -type f \( -name '*.js' -o -name '*.mjs' \) -print0 | xargs -0 -n1 node --check
node scripts/static-check.mjs
node -e "const p=require('./package.json'); if(p.version!=='9.7.0') process.exit(1); console.log('✅ Version',p.version)"

say "4/6 ทดสอบ Logic กับเคสจริงที่ v9.6 เคยเป็น WAIT"
python - "$TEST_FILE" <<'PYTEST'
from pathlib import Path
import sys
s=Path('app/api/gold/route.js').read_text()
start=s.index('function combinedTradeDecision')
end=s.index('\nfunction m1SafeTime', start)
mstart=s.index('function m1SafeTime', end)
mend=s.index('\n\nfunction buildPayload', mstart)
code=s[start:end]+'\n'+s[mstart:mend]+r'''
const f3={candle:3,direction:"WAIT",rawDirection:"WAIT",confidence:48,probabilities:{buy:37,sell:20,wait:43},backtestSamples:24,backtestAccuracy:54};
const f5={candle:5,direction:"WAIT",rawDirection:"WAIT",confidence:48,probabilities:{buy:34,sell:23,wait:43},backtestSamples:24,backtestAccuracy:54};
const oneMinute={forecasts:[null,null,f3,null,f5],indicators:{atr:1.43125,rsi:58.4,macdHistogram:0.01},levels:{support:3320,resistance:3330},riskLevel:"MEDIUM",historicalPattern:{validation:{samples:58,accuracy:31},currentPatternAt:"sample"},backtest:{patternSamples:24,patternAccuracy:54},reliability:31,entryScore:20,trendScore:58};
const fiveMinute={trendBias:"BULLISH",trendScore:62};
const result=combinedTradeDecision(oneMinute,fiveMinute,3325);
if(result.status!=="ENTRY" || result.entryTier!=="OPPORTUNITY" || result.direction!=="BUY"){
  console.error(JSON.stringify(result,null,2)); process.exit(1);
}
console.log(`✅ Regression test: ${result.decision} · probability ${result.targetProbability} · score ${result.signalScore} · confirmations ${result.confirmationCount}`);
'''
Path(sys.argv[1]).write_text(code)
PYTEST
node "$TEST_FILE"
grep -q 'opportunityMinProbability: activeSignalMode ? 50' lib/config.ts
grep -q 'entryTier === "OPPORTUNITY"' lib/alerts.ts
printf '✅ LINE OPPORTUNITY gate ตรวจพบ\n'

say "5/6 ตั้ง Git identity แบบซ่อนอีเมล และ Commit"
REMOTE_URL=$(git remote get-url origin 2>/dev/null || true)
GITHUB_USER=$(printf '%s' "$REMOTE_URL" | sed -E 's#^.*github\.com[:/]([^/]+)/.*#\1#')
if [[ -z "$GITHUB_USER" || "$GITHUB_USER" == "$REMOTE_URL" ]]; then
  GITHUB_USER=$(git config user.name || true)
fi
[[ -n "$GITHUB_USER" ]] || GITHUB_USER="github-user"
git config user.name "$GITHUB_USER"
git config user.email "$GITHUB_USER@users.noreply.github.com"

rm -f v97.sh
git add -A
if git diff --cached --quiet; then
  say "ไม่มีไฟล์ใหม่ให้ Commit — v9.7 ถูกติดตั้งอยู่แล้ว"
else
  git commit -m "Upgrade GOLD PULSE X to v9.7 Opportunity Signal"
fi

say "6/6 Push ไป GitHub"
git push origin HEAD:main

printf '\n\033[1;32mSUCCESS: v9.7 Opportunity Signal pushed to GitHub.\033[0m\n'
printf 'Vercel จะ Deploy อัตโนมัติ\n'
printf 'OPPORTUNITY: probability >= 50 / score >= 58 / edge >= 8 / อย่างน้อย 2 confirmations\n'
printf 'ACTIVE และ CONFIRMED ใช้เกณฑ์เดิม; Risk HIGH ยังถูกบล็อก; cooldown 20 นาที\n'
printf 'เป้าหมายคือเพิ่มโอกาสเข้าใกล้ 20 alerts ต่อวัน ไม่รับประกันจำนวนหรือผลกำไร\n'
